def norm(s): return re.sub(r'\s+', ' ', s.replace('\f', ' ')).strip()
fails = 0
out = [['concept_id', 'concept_label', 'form', 'language', 'jurisdiction', 'usage_type', 'scope_note', 'attestation_tier', 'source', 'locator', 'quote', 'conflation_note', 'text_file', 'quote_verified']]
for cid, lab, form, ut, sc, k, loc, q, cn in ROWS:
    title, iss, url, tf = S[k]
    t = norm(open(f'{D}/text/{tf}.txt', encoding='utf-8').read())
    ok = norm(q) in t
    if not ok or len(q.split()) > 25:
        fails += 1; print('FAIL', cid, form, k, 'words=%d' % len(q.split()), file=sys.stderr)
    out.append([cid, lab, form, 'it', 'IT', ut, sc, str(TIER[k]), f'{title} — {iss} — {url}', loc, q, cn, tf + '.txt', 'yes' if ok else 'NO'])
with open(f'{D}/equivalents.tsv', 'w', encoding='utf-8', newline='') as f:
    csv.writer(f, delimiter='\t', lineterminator='\n').writerows(out)
print(f'rows {len(out)-1}, failures {fails}')
sys.exit(1 if fails else 0)
